package org.opensourcepingpong.membership;
import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="rating_ledger") public class RatingLedger { @Id private UUID id; @Column(name="user_id") private UUID userId; @Column(name="source_type") private String sourceType; @Column(name="rating_delta") private int ratingDelta; @Column(name="rating_after") private int ratingAfter; @Column(name="rule_version") private String ruleVersion; @Column(name="created_at") private Instant createdAt; protected RatingLedger(){} public static RatingLedger initial(UUID userId){RatingLedger l=new RatingLedger();l.id=UUID.randomUUID();l.userId=userId;l.sourceType="INITIAL";l.ratingDelta=1400;l.ratingAfter=1400;l.ruleVersion="V1";l.createdAt=Instant.now();return l;} }
